PT_MIRANTTE = '''<section id="mirantte" class="chapter"><h2>2004–2008 — Mirantte News: produto digital, aquisição e a descoberta de Search</h2><p>O <strong>Mirantte News</strong> era um guia de produtos e serviços que ia além de um mecanismo regional de busca. Empresas selecionadas contratavam planos anuais que combinavam destaque na home, indexação em uma das cerca de vinte categorias do portal e um hot-site próprio, com fotografias profissionais, logotipo, contatos, matéria produzida pela jornalista <strong>Tatiana Cavalcanti</strong> e recursos de geolocalização e rotas desenvolvidos em parceria com a <strong>MapLink/UOL</strong>.</p><p>Marcelo Nicchio conduzia o projeto em sociedade com <strong>Luiz Kechichian</strong>, proprietário do Grupo Mirantte. A operação era enxuta: além de Nicchio, a equipe chegou a reunir um webmaster, um profissional comercial e uma auxiliar administrativa.</p><p>À medida que os contratos se acumulavam, porém, surgiu um problema central: <strong>tráfego</strong>. O volume orgânico do portal não era suficiente para alimentar de maneira equilibrada todas as categorias e entregar a exposição esperada aos anunciantes.</p><p>Foi nesse contexto que um contato da MapLink intermediou, por Skype, uma conversa entre Nicchio e <strong>Tiago Luz</strong>, um dos profissionais pioneiros de Search Marketing no Brasil, então radicado em Curitiba. A solução discutida era objetiva: adquirir tráfego para as categorias com maior concentração de anunciantes, incorporando esse custo ao próprio modelo comercial do portal.</p><p>As primeiras campanhas de aquisição funcionaram e foram mantidas por alguns meses. Ainda assim, o modelo econômico do Mirantte News tornou-se progressivamente difícil de sustentar. A operação foi reduzida e transferida para home office, permanecendo Nicchio e o webmaster <strong>Renato Carriel</strong>. Mais tarde, o projeto mudou de posicionamento e passou a abranger a cidade de São Paulo sob o nome <strong>Procure SP</strong>, mas acabou encerrando suas atividades.</p><p>O projeto terminou; o problema que ele havia apresentado, porém, abriu uma nova direção profissional. <strong>Search permaneceu.</strong></p><div class="inline-records"><a class="inline-record" href="/assets/archive/mirantte-news-card.webp" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/mirantte-news-card.webp" loading="lazy" decoding="async" alt="Cartão profissional do Mirantte News com marca, slogan e nome Marcelo Nicchio."><span><strong>Mirantte News · cartão profissional</strong><small>Abrir registro ↗</small></span></a></div></section>'''

EN_MIRANTTE = '''<section id="mirantte" class="chapter"><h2>2004–2008 — Mirantte News: digital product, acquisition and the discovery of Search</h2><p><strong>Mirantte News</strong> was a products-and-services guide that went beyond a regional search mechanism. Selected companies signed annual plans combining homepage prominence, indexing in one of roughly twenty portal categories and a dedicated hot-site with professional photography, logo, contact information, an article produced by journalist <strong>Tatiana Cavalcanti</strong>, and geolocation and route-planning features developed through a partnership with <strong>MapLink/UOL</strong>.</p><p>Marcelo Nicchio ran the project in partnership with <strong>Luiz Kechichian</strong>, owner of Grupo Mirantte. The operation was lean: besides Nicchio, the team came to include a webmaster, a commercial contact and an administrative assistant.</p><p>As contracts accumulated, however, a central problem emerged: <strong>traffic</strong>. The portal's organic volume was not enough to feed all categories evenly and deliver the exposure advertisers expected.</p><p>In that context, a MapLink contact arranged a Skype conversation between Nicchio and <strong>Tiago Luz</strong>, one of the early Search Marketing professionals in Brazil, then based in Curitiba. The solution discussed was straightforward: buy traffic for the categories with the greatest concentration of advertisers and incorporate that cost into the portal's own commercial model.</p><p>The first acquisition campaigns worked and remained active for several months. Even so, Mirantte News became progressively difficult to sustain economically. The operation was reduced and moved to a home-office model, leaving Nicchio and webmaster <strong>Renato Carriel</strong>. Later, the guide shifted its positioning and expanded its scope to the city of São Paulo under the name <strong>Procure SP</strong>, but eventually ceased operations.</p><p>The project ended, but the problem it had presented opened a new professional direction. <strong>Search remained.</strong></p><div class="inline-records"><a class="inline-record" href="/assets/archive/mirantte-news-card.webp" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/mirantte-news-card.webp" loading="lazy" decoding="async" alt="Mirantte News professional card with brand, tagline and the name Marcelo Nicchio."><span><strong>Mirantte News · professional card</strong><small>Open record ↗</small></span></a></div></section>'''

PT_SEM = '''<section id="sem" class="chapter"><h2>2008–2009 — das primeiras contas à profissionalização em Search</h2><p>Em 2008, Nicchio começou a administrar de maneira intuitiva e autodidata contas de pequeno porte de Google AdWords, entre elas o restaurante <strong>O Caipira</strong>, um estúdio de yoga, um serviço de buffet, um ateliê de pintura e uma corretora de seguros. Eram operações pequenas, mas permitiram experimentar diretamente estrutura de campanhas, palavras-chave, segmentação, custos e retorno.</p><p>Ainda naquele ano, conheceu a profissional carioca <strong>Louise Martins</strong> durante uma visita dela a São Paulo. Em uma cafeteria, Louise abriu o notebook e mostrou uma operação de AdWords em uma escala que Nicchio ainda não havia encontrado: uma conta de grande porte, estruturada simultaneamente para diferentes países. A dimensão daquela operação causou forte impressão. Search deixava de parecer apenas uma solução aprendida para resolver um problema do Mirantte e passava a se apresentar como um campo profissional muito maior.</p><p>Pouco depois, Louise seria personagem da reportagem <strong>“Com a grife do Google”</strong>, publicada pela revista <em>INFO</em> em julho de 2008, sobre a então pequena e disputada comunidade de profissionais certificados como Google Advertising Professional — GAP. <a href="https://datassette.org/revistas/info-informatica-revistas/info-exame-no-269" target="_blank" rel="noopener noreferrer">INFO Exame nº 269 · jul. 2008 ↗</a></p><p>A experiência reforçou a decisão de Nicchio de entrar profissionalmente no campo. Em <strong>2009</strong>, matriculou-se em uma das primeiras turmas do curso de Google AdWords da <strong>Goobec</strong>, criada em 2008 como primeira parceira oficial do Google na América Latina para treinamentos. Durante a imersão, ministrada por <strong>João Dalla</strong>, conheceu outro aluno: <strong>Herik Mourão</strong>. <a href="https://www.goobec.com.br/sobre-a-goobec" target="_blank" rel="noopener noreferrer">Histórico da Goobec ↗</a></p><p>Depois do curso, continuou administrando pequenas contas enquanto estudava intensamente a documentação técnica disponibilizada pelo Google para anunciantes e profissionais ao longo de 2009.</p></section>'''

EN_SEM = '''<section id="sem" class="chapter"><h2>2008–2009 — from first accounts to professionalization in Search</h2><p>In 2008, Nicchio began managing small Google AdWords accounts intuitively and through self-directed learning, including the <strong>O Caipira</strong> restaurant, a yoga studio, a buffet service, a painting atelier and an insurance brokerage. These were small operations, but they allowed him to work directly with campaign structure, keywords, segmentation, costs and return.</p><p>That same year, he met Rio de Janeiro-based professional <strong>Louise Martins</strong> during one of her visits to São Paulo. At a café, Louise opened her laptop and showed him an AdWords operation on a scale Nicchio had not yet encountered: a large account structured simultaneously across different countries. The scale of that operation made a strong impression. Search no longer looked only like a solution learned to address Mirantte's traffic problem; it began to appear as a much larger professional field.</p><p>Soon afterward, Louise would be featured in <strong>“Com a grife do Google”</strong>, an article published by <em>INFO</em> magazine in July 2008 about the then-small and competitive community of Google Advertising Professional — GAP certified professionals. <a href="https://datassette.org/revistas/info-informatica-revistas/info-exame-no-269" target="_blank" rel="noopener noreferrer">INFO Exame no. 269 · Jul. 2008 ↗</a></p><p>The experience reinforced Nicchio's decision to enter the field professionally. In <strong>2009</strong>, he enrolled in one of the first Google AdWords classes at <strong>Goobec</strong>, founded in 2008 as Google's first official training partner in Latin America. During the immersion course taught by <strong>João Dalla</strong>, he met another student: <strong>Herik Mourão</strong>. <a href="https://www.goobec.com.br/sobre-a-goobec" target="_blank" rel="noopener noreferrer">Goobec history ↗</a></p><p>After the course, he continued managing small accounts while studying Google's technical documentation for advertisers and professionals intensively throughout 2009.</p></section>'''

PT_COOKIEWEB = '''<section id="cookieweb" class="chapter"><h2>2010–2012 — Beleza na Web e CookieWEB: Search em escala</h2><h3>2010 — Herik Mourão e Beleza na Web</h3><p>No primeiro semestre de 2010, Herik Mourão procurou Nicchio com uma proposta que mudaria novamente a escala de seu trabalho: assumir a operação de mídia da <strong>Beleza na Web</strong>.</p><p>Era a primeira conta de grande porte sob sua responsabilidade direta, com estrutura complexa, grande volume de tráfego e forte orientação a <strong>ROI</strong>. Naquele momento, o investimento mensal em mídia era de aproximadamente <strong>US$ 50 mil</strong>.</p><p>A operação começou ainda na casa de Nicchio. Herik fazia visitas frequentes e funcionava como ponte com <strong>Alexandre Serodio</strong>, proprietário da Beleza na Web. Entre planilhas, relatórios e sucessivas reconstruções de campanha, Nicchio aprofundou uma forma de otimização por camadas: categorias, produtos, termos de busca, higienização de palavras-chave e avaliação contínua de desempenho.</p><p>Foi uma mudança importante. A experiência que havia começado com pequenas contas passava agora a envolver uma operação de e-commerce de grande porte, em que decisões de mídia precisavam responder diretamente a faturamento e retorno.</p><h3>2010 — criação da área de mídia da CookieWEB</h3><p>Por volta de junho de 2010, Herik apresentou Nicchio a <strong>Natan Sztamfater</strong>, proprietário de uma pequena agência localizada no Bom Retiro, em São Paulo: a <strong>CookieWEB</strong>. Naquele momento, a agência tinha aproximadamente cinco funcionários e concentrava sua atuação na criação de sites e em ações de e-mail marketing. Paralelamente, Herik negociava sua entrada no negócio para criar uma nova frente: <strong>Mídia Digital</strong>.</p><p>Pouco depois, a operação foi formalizada. Beleza na Web, <strong>PortCasa</strong> e outras duas contas menores passaram a ser administradas a partir da CookieWEB, inaugurando uma nova área dentro da agência e uma nova etapa profissional para Nicchio e Herik.</p><p>Em paralelo aos primeiros meses dessa operação, Nicchio decidiu obter as certificações <strong>Google Advertising Professional — GAP</strong>. Naquele período, cada prova exigia a compra de um voucher de <strong>US$ 50</strong> e não havia repetição gratuita em caso de reprovação. A preparação envolveu estudo obsessivo da documentação técnica do Google. A aprovação teve peso profissional e também pessoal: era a consolidação formal de um campo em que havia entrado poucos anos antes de maneira essencialmente autodidata.</p><div class="inline-records"><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap01.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap01.jpg" loading="lazy" decoding="async" alt="Certificado Google Advertising Professional de Marcelo Nicchio, registro 1 de 3."><span><strong>Google GAP · certificado 1/3</strong><small>Abrir registro ↗</small></span></a><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap02.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap02.jpg" loading="lazy" decoding="async" alt="Certificado Google Advertising Professional de Marcelo Nicchio, registro 2 de 3."><span><strong>Google GAP · certificado 2/3</strong><small>Abrir registro ↗</small></span></a><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap03.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap03.jpg" loading="lazy" decoding="async" alt="Certificado Google Advertising Professional de Marcelo Nicchio, registro 3 de 3."><span><strong>Google GAP · certificado 3/3</strong><small>Abrir registro ↗</small></span></a></div><h3>2010–2011 — construção de equipe e crescimento</h3><p>O volume operacional cresceu rapidamente. Tornou-se necessário contratar estagiários para auxiliar na gestão das contas. O primeiro deles foi <strong>Anderson Ramos</strong>, estudante de Administração, selecionado inicialmente por Herik e treinado intensamente por Nicchio. Anderson se tornou um dos principais integrantes da equipe e posteriormente foi efetivado. Outros estagiários e analistas foram incorporados conforme novos clientes chegavam.</p><p>Nesse estágio, Herik ocupava a posição de <strong>Gerente de SEM</strong>, enquanto Nicchio atuava como <strong>Coordenador</strong>, combinando coordenação, operação e treinamento da equipe.</p><p>Logo no segundo mês dessa nova fase, <strong>Marcel Werdesheim</strong> tornou-se sócio da agência e, ao lado de Natan, participou de novos investimentos e da expansão física da empresa. A CookieWEB deixou o pequeno escritório do Bom Retiro e se transferiu para uma sala comercial maior em Perdizes, preparada para uma equipe de dezenas de profissionais.</p><figure class="thread-media thread-media--linked"><a href="/assets/archive/internet/cookieweb/cookieweb_02.jpg" target="_blank" rel="noopener noreferrer" aria-label="Abrir foto da equipe da CookieWEB em tamanho maior"><img src="/assets/archive/internet/cookieweb/cookieweb_02.jpg" loading="lazy" decoding="async" alt="Equipe da CookieWEB em um momento de confraternização com sorvetes."></a><figcaption><strong>Equipe da CookieWEB.</strong><span class="thread-media-note">Um dos registros do cotidiano da equipe durante o período de expansão da operação.</span><a class="thread-media-open" href="/assets/archive/internet/cookieweb/cookieweb_02.jpg" target="_blank" rel="noopener noreferrer">Abrir imagem em tamanho maior ↗</a></figcaption></figure><h3>2011–2012 — Gerência de SEM, escala e operação</h3><p>Já na nova sede, a equipe continuou crescendo à medida que novas contas eram conquistadas. Herik e Nicchio participavam das reuniões com clientes, enquanto Nicchio coordenava diretamente a operação de mídia junto aos analistas.</p><p>No primeiro semestre de 2011, Herik deixou a CookieWEB para assumir uma posição de mídia na <strong>Beleza na Web</strong>. Com sua saída, Nicchio tornou-se <strong>Gerente de SEM</strong> e Anderson Ramos assumiu a coordenação operacional.</p><p>A mudança ampliou significativamente suas responsabilidades. Além da estratégia e supervisão das contas, passou a conduzir reuniões periódicas com clientes, contratação de profissionais, acompanhamento de KPIs e organização geral da área. Para aumentar a capacidade de supervisão, a equipe adotou a plataforma canadense <strong>Acquisio</strong>, que permitia acompanhar indicadores e otimizações em diferentes contas, e o <strong>Asana</strong>, utilizado para estruturar processos recorrentes de criação, gestão e otimização de campanhas.</p><p>No final de 2011, a CookieWEB já administrava simultaneamente <strong>mais de 22 contas</strong>, em uma estimativa conservadora. Entre elas estavam <strong>Marcyn, Aramis, Shoulder, Star Point, CNS, Norah</strong> e outras marcas de médio porte. A área de mídia chegou a reunir <strong>seis analistas, além de estagiários</strong>, enquanto a agência como um todo alcançava cerca de trinta profissionais. Uma matéria contemporânea sobre a expansão da CookieWEB registra vários desses mesmos clientes no portfólio da agência. <a href="https://www.alshop.com.br/portal/cookieweb-adquire-parte-da-profite-por-r-3-2-milhoes/" target="_blank" rel="noopener noreferrer">Alshop · 18 jul. 2012 ↗</a></p><p>A variedade das contas também ampliou enormemente a experiência de Nicchio. A equipe atendia negócios com produtos, margens, ciclos de compra e públicos radicalmente diferentes — de sex shops a fabricantes de cadeiras de rodas. O trabalho mostrava, na prática, que mídia eficiente não dependia apenas da campanha: operação, produto, preço, logística, conversão e capacidade empresarial determinavam igualmente o resultado.</p><p>Essa convivência com dezenas de modelos de negócio aprofundou uma visão de performance que já não se restringia a palavras-chave ou anúncios.</p><h3>Pessoas, cultura e pertencimento</h3><p>À medida que a equipe crescia, Nicchio também passou a se preocupar com um aspecto menos quantitativo da operação: <strong>pertencimento</strong>. Eventos internos como a festa junina funcionavam como momentos de convivência fora da pressão cotidiana das contas.</p><p>No final de 2011, inspirado por práticas que observava em agências mais jovens do mercado, propôs algo até então incomum na cultura da CookieWEB: fechar a empresa por um dia e levar toda a equipe ao <strong>Hopi Hari</strong>. A proposta encontrou resistência inicial. Para Nicchio, porém, a justificativa era simples: uma operação que exigia tanto das pessoas precisava também criar experiências positivas para quem a sustentava.</p><p>A agência fechou naquele dia. Alguns clientes mais próximos reclamaram; funcionários e sócios foram juntos ao parque. Na memória de Nicchio, foi um dia especialmente feliz — e uma pequena mudança na cultura de uma empresa que havia crescido muito rapidamente.</p><!-- gallery:cookieweb --><h3>2012 — encerramento do ciclo CookieWEB</h3><p>Em 2012, a estrutura construída no ano anterior continuou operando em grande escala. Além da pressão permanente das contas, havia o desafio de formar e reter uma equipe muito jovem. Nicchio tinha então 35 anos; boa parte dos analistas estava na faixa dos 22 a 25.</p><p>Entre os profissionais que ganharam maior responsabilidade estavam <strong>Anderson Ramos</strong> e <strong>Camila Jordão</strong>. Nicchio via capacidades complementares nos dois: Anderson possuía forte domínio técnico, enquanto Camila se destacava pela liderança. Antes de sair de férias naquele ano, deixou a continuidade da operação especialmente apoiada neles.</p><p>Em <strong>18 de julho de 2012</strong>, Natan Sztamfater e Marcel Werdesheim anunciaram a aquisição de participação na agência <strong>ProfitE</strong>, então instalada na Vila Olímpia. A operação, divulgada publicamente no mesmo dia por <strong>R$ 3,2 milhões</strong>, implicaria também uma mudança física da CookieWEB para aquela região. <a href="https://www.alshop.com.br/portal/cookieweb-adquire-parte-da-profite-por-r-3-2-milhoes/" target="_blank" rel="noopener noreferrer">Registro contemporâneo da aquisição ↗</a></p><p>Para Nicchio, a mudança acrescentaria mais de uma hora ao deslocamento diário num momento em que a intensidade da operação já havia comprometido significativamente sua qualidade de vida. Depois de pouco mais de dois anos de crescimento acelerado, decidiu encerrar seu ciclo na agência.</p><p>Natan e Marcel tentaram convencê-lo a permanecer durante algumas semanas. Nicchio, porém, não estava deixando a CookieWEB para assumir outra posição. A decisão era interromper o ritmo, viajar, respirar e voltar a considerar novas oportunidades depois.</p><p>Saiu da empresa pela porta da frente, deixando claro que <strong>qualidade de vida havia se tornado um limite inegociável</strong>.</p></section>'''

EN_COOKIEWEB = '''<section id="cookieweb" class="chapter"><h2>2010–2012 — Beleza na Web and CookieWEB: Search at scale</h2><h3>2010 — Herik Mourão and Beleza na Web</h3><p>In the first half of 2010, Herik Mourão approached Nicchio with a proposal that would once again change the scale of his work: take over the media operation for <strong>Beleza na Web</strong>.</p><p>It was the first large account under his direct responsibility, with a complex structure, high traffic volume and strong <strong>ROI</strong> pressure. At that point, monthly media investment was approximately <strong>US$50,000</strong>.</p><p>The operation began from Nicchio's home. Herik visited frequently and served as the bridge to <strong>Alexandre Serodio</strong>, owner of Beleza na Web. Amid spreadsheets, reports and successive campaign rebuilds, Nicchio deepened a layered optimization approach: categories, products, search terms, keyword cleanup and continuous performance assessment.</p><p>It was an important shift. Experience that had begun with small accounts now involved a large e-commerce operation in which media decisions had to answer directly to revenue and return.</p><h3>2010 — building CookieWEB's media operation</h3><p>Around June 2010, Herik introduced Nicchio to <strong>Natan Sztamfater</strong>, owner of a small agency in São Paulo's Bom Retiro district: <strong>CookieWEB</strong>. At the time, the agency had approximately five employees and focused on website creation and email marketing. In parallel, Herik was negotiating his entry into the business to open a new front: <strong>Digital Media</strong>.</p><p>Soon afterward, the operation was formalized. Beleza na Web, <strong>PortCasa</strong> and two smaller accounts began to be managed from CookieWEB, opening a new area inside the agency and a new professional stage for Nicchio and Herik.</p><p>During the first months of this operation, Nicchio decided to obtain the <strong>Google Advertising Professional — GAP</strong> certifications. At the time, each exam required a <strong>US$50</strong> voucher and there was no free retake after a failed attempt. Preparation involved obsessive study of Google's technical documentation. Passing the exams carried both professional and personal weight: it was the formal consolidation of a field he had entered only a few years earlier largely through self-directed learning.</p><div class="inline-records"><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap01.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap01.jpg" loading="lazy" decoding="async" alt="Marcelo Nicchio Google Advertising Professional certificate, record 1 of 3."><span><strong>Google GAP · certificate 1/3</strong><small>Open record ↗</small></span></a><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap02.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap02.jpg" loading="lazy" decoding="async" alt="Marcelo Nicchio Google Advertising Professional certificate, record 2 of 3."><span><strong>Google GAP · certificate 2/3</strong><small>Open record ↗</small></span></a><a class="inline-record" href="/assets/archive/internet/google-gap/marcelonicchio-gap03.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/archive/internet/google-gap/marcelonicchio-gap03.jpg" loading="lazy" decoding="async" alt="Marcelo Nicchio Google Advertising Professional certificate, record 3 of 3."><span><strong>Google GAP · certificate 3/3</strong><small>Open record ↗</small></span></a></div><h3>2010–2011 — building the team and growing the agency</h3><p>Operational volume grew quickly. Hiring interns to support account management became necessary. The first was <strong>Anderson Ramos</strong>, a Business Administration student initially selected by Herik and trained intensively by Nicchio. Anderson became one of the key members of the team and was later hired permanently. More interns and analysts joined as new clients arrived.</p><p>At this stage, Herik held the position of <strong>SEM Manager</strong>, while Nicchio worked as <strong>Coordinator</strong>, combining coordination, hands-on operation and team training.</p><p>In the second month of this new phase, <strong>Marcel Werdesheim</strong> became a partner in the agency and, together with Natan, participated in new investment and the company's physical expansion. CookieWEB left its small Bom Retiro office and moved to a larger commercial space in Perdizes, prepared for a team of dozens of professionals.</p><figure class="thread-media thread-media--linked"><a href="/assets/archive/internet/cookieweb/cookieweb_02.jpg" target="_blank" rel="noopener noreferrer" aria-label="Open the CookieWEB team photo at full size"><img src="/assets/archive/internet/cookieweb/cookieweb_02.jpg" loading="lazy" decoding="async" alt="CookieWEB team during an informal moment with ice cream."></a><figcaption><strong>CookieWEB team.</strong><span class="thread-media-note">One of the surviving records of everyday team life during the operation's expansion.</span><a class="thread-media-open" href="/assets/archive/internet/cookieweb/cookieweb_02.jpg" target="_blank" rel="noopener noreferrer">Open full-size image ↗</a></figcaption></figure><h3>2011–2012 — SEM management, scale and operations</h3><p>At the new office, the team continued to grow as new accounts were won. Herik and Nicchio took part in client meetings, while Nicchio directly coordinated the media operation with the analysts.</p><p>In the first half of 2011, Herik left CookieWEB to take a media role at <strong>Beleza na Web</strong>. With his departure, Nicchio became <strong>SEM Manager</strong>, while Anderson Ramos took over operational coordination.</p><p>The change significantly expanded Nicchio's responsibilities. In addition to account strategy and supervision, he began conducting periodic client meetings, hiring professionals, monitoring KPIs and organizing the area as a whole. To improve oversight, the team adopted the Canadian platform <strong>Acquisio</strong>, used to monitor indicators and optimizations across different accounts, and <strong>Asana</strong>, used to structure recurring campaign creation, management and optimization processes.</p><p>By the end of 2011, CookieWEB was managing <strong>more than 22 accounts simultaneously</strong>, by a conservative estimate. They included <strong>Marcyn, Aramis, Shoulder, Star Point, CNS, Norah</strong> and other mid-sized brands. The media area grew to <strong>six analysts plus interns</strong>, while the agency as a whole reached roughly thirty professionals. A contemporary article about CookieWEB's expansion lists several of these same clients in the agency's portfolio. <a href="https://www.alshop.com.br/portal/cookieweb-adquire-parte-da-profite-por-r-3-2-milhoes/" target="_blank" rel="noopener noreferrer">Alshop · Jul. 18, 2012 ↗</a></p><p>The variety of accounts also broadened Nicchio's experience enormously. The team served businesses with radically different products, margins, purchasing cycles and audiences — from sex shops to wheelchair manufacturers. In practice, the work showed that efficient media did not depend only on the campaign: operations, product, pricing, logistics, conversion and business capability shaped results just as strongly.</p><p>Living with dozens of business models deepened a view of performance that was no longer limited to keywords or ads.</p><h3>People, culture and belonging</h3><p>As the team grew, Nicchio also began focusing on a less quantitative dimension of the operation: <strong>belonging</strong>. Internal events such as the agency's June festival created moments of shared life outside the daily pressure of the accounts.</p><p>At the end of 2011, inspired by practices he observed at younger agencies in the market, he proposed something then unusual in CookieWEB's culture: close the agency for a day and take the entire team to <strong>Hopi Hari</strong>. The proposal initially met resistance. For Nicchio, however, the reasoning was simple: an operation that demanded so much from people also needed to create positive experiences for those sustaining it.</p><p>The agency closed that day. Some close clients complained; employees and partners went to the park together. In Nicchio's memory, it was an especially happy day — and a small change in the culture of a company that had grown very quickly.</p><!-- gallery:cookieweb --><h3>2012 — closing the CookieWEB cycle</h3><p>In 2012, the structure built during the previous year continued operating at large scale. Beyond the constant pressure of the accounts, there was the challenge of developing and retaining a very young team. Nicchio was 35 at the time; many analysts were between 22 and 25.</p><p>Among the professionals who took on greater responsibility were <strong>Anderson Ramos</strong> and <strong>Camila Jordão</strong>. Nicchio saw complementary strengths in them: Anderson had strong technical command, while Camila stood out for leadership. Before taking a vacation that year, he left the continuity of the operation especially supported by the two of them.</p><p>On <strong>July 18, 2012</strong>, Natan Sztamfater and Marcel Werdesheim announced the acquisition of a stake in <strong>ProfitE</strong>, then located in Vila Olímpia. The deal, publicly reported that same day at <strong>R$3.2 million</strong>, would also move CookieWEB's physical operation to that area. <a href="https://www.alshop.com.br/portal/cookieweb-adquire-parte-da-profite-por-r-3-2-milhoes/" target="_blank" rel="noopener noreferrer">Contemporary acquisition report ↗</a></p><p>For Nicchio, the move would add more than an hour to his daily commute at a time when the intensity of the operation had already significantly affected his quality of life. After a little over two years of accelerated growth, he decided to end his cycle at the agency.</p><p>Natan and Marcel spent several weeks trying to convince him to stay. Nicchio, however, was not leaving CookieWEB to take another position. The decision was to interrupt the pace, travel, breathe and consider new opportunities later.</p><p>He left the company on good terms, making clear that <strong>quality of life had become a non-negotiable limit</strong>.</p></section>'''


def replace_section(path: Path, section_id: str, replacement: str) -> None:
    text = path.read_text(encoding="utf-8")
    pattern = rf'<section id="{re.escape(section_id)}" class="chapter">.*?</section>'
    updated, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(f"{path}: expected one section #{section_id}, replaced {count}")
    path.write_text(updated, encoding="utf-8")


def upsert_gallery() -> None:
    path = ROOT / "data/galleries.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    data["updated"] = "2026-08-28"
    items = []

    def add(item_id: str, source: str, pt: str, en: str) -> None:
        items.append({"id": item_id, "source": source, "caption": {"pt": pt, "en": en}})

    birthday = [
        "cookieweb01-aniversario_marcelo2012_01.jpg",
        "cookieweb01-aniversario_marcelo2012_02.jpg",
        "cookieweb01-aniversario_marcelo2012-03.jpg",
        "cookieweb01-aniversario_marcelo2012-04.jpg",
    ]
    for idx, source in enumerate(birthday, 1):
        add(f"{idx:02d}", source, "Aniversário de Marcelo Nicchio na CookieWEB, 2012.", "Marcelo Nicchio's birthday at CookieWEB, 2012.")

    for offset, source in enumerate([
        "cookieweb02-festajunina_01.jpg",
        "cookieweb02-festajunina_02.jpg",
        "cookieweb02-festajunina_03.jpg",
    ], 5):
        add(f"{offset:02d}", source, "Festa junina da equipe da CookieWEB, 2011.", "CookieWEB team at the agency's June festival, 2011.")

    hopi_sources = ["cookieweb03-hopihari_01.JPG"] + [f"cookieweb03-hopihari_{i:02d}.jpg" for i in range(2, 11)]
    for offset, source in enumerate(hopi_sources, 8):
        add(f"{offset:02d}", source, "Equipe da CookieWEB no Hopi Hari, confraternização de fim de ano de 2011.", "CookieWEB team at Hopi Hari for the 2011 year-end gathering.")

    add("18", "cookieweb04-marcelonicchio_natansztamfater.jpg", "Marcelo Nicchio e Natan Sztamfater no aniversário de Nicchio, 2012.", "Marcelo Nicchio and Natan Sztamfater at Nicchio's birthday, 2012.")
    add("19", "cookieweb05-marcelonicchio_e_equipe.jpg", "Marcelo Nicchio com integrantes da equipe da CookieWEB.", "Marcelo Nicchio with members of the CookieWEB team.")
    add("20", "cookieweb06-prontoparaasferias.jpg", "Mala “ROI Maniac” antes das férias de Marcelo Nicchio, 2012.", "The “ROI Maniac” suitcase before Marcelo Nicchio's vacation, 2012.")

    gallery = {
        "id": "cookieweb",
        "sourceRoot": "assets/archive/internet/cookieweb",
        "targets": {"pt": ["pt/internet/index.html"], "en": ["en/internet/index.html"]},
        "title": {"pt": "Fotos da CookieWEB", "en": "CookieWEB photos"},
        "items": items,
    }
    galleries = data.setdefault("galleries", [])
    for i, existing in enumerate(galleries):
        if existing.get("id") == "cookieweb":
            galleries[i] = gallery
            break
    else:
        galleries.append(gallery)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def main() -> None:
    pt = ROOT / "pt/internet/index.html"
    en = ROOT / "en/internet/index.html"
    replace_section(pt, "mirantte", PT_MIRANTTE)
    replace_section(pt, "sem", PT_SEM)
    replace_section(pt, "cookieweb", PT_COOKIEWEB)
    replace_section(en, "mirantte", EN_MIRANTTE)
    replace_section(en, "sem", EN_SEM)
    replace_section(en, "cookieweb", EN_COOKIEWEB)
    upsert_gallery()
    print("Applied Block 3A editorial source changes and CookieWEB gallery seed.")


if __name__ == "__main__":
    main()
